renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const ambient = new THREE.AmbientLight(0xffffff, 0.28);
const keyLight = new THREE.DirectionalLight(0xfff5e6, 1.45);
keyLight.position.set(6, 4, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xcce0ff, 0.55);
fillLight.position.set(-8, 2, 6);

const rimLight = new THREE.SpotLight(0xaaddff, 0.9);
rimLight.position.set(-6, 6, -6);
rimLight.lookAt(0, 0, 0);

scene.add(ambient, keyLight, fillLight, rimLight);

const textureLoader = new THREE.TextureLoader();
const textureBase = 'https://rawcdn.githack.com/mrdoob/three.js/r128/examples/textures/planets';
// Fallback texture usage: Earth assets not in curated catalog; using public Three.js example textures
const earthMap = textureLoader.load(`${textureBase}/earth_atmos_2048.jpg`);
const earthNormal = textureLoader.load(`${textureBase}/earth_normal_2048.jpg`);
const earthSpec = textureLoader.load(`${textureBase}/earth_specular_2048.jpg`);
const cloudMap = textureLoader.load(`${textureBase}/earth_clouds_1024.png`);

const earthGroup = new THREE.Group();
scene.add(earthGroup);

const earthGeo = new THREE.SphereGeometry(1, 128, 128);
const earthMat = new THREE.MeshPhysicalMaterial({
  map: earthMap,
  normalMap: earthNormal,
  normalScale: new THREE.Vector2(0.85, 0.85),
  roughness: 0.85,
  metalness: 0.1,
  clearcoat: 1.0,
  clearcoatMap: earthSpec,
  clearcoatRoughness: 0.15,
  envMapIntensity: 1.0
});
const earth = new THREE.Mesh(earthGeo, earthMat);
earth.castShadow = true;
earth.receiveShadow = true;
earthGroup.add(earth);

const cloudGeo = new THREE.SphereGeometry(1.018, 96, 96);
const cloudMat = new THREE.MeshStandardMaterial({
  map: cloudMap,
  transparent: true,
  opacity: 0.85,
  depthWrite: false,
  side: THREE.DoubleSide,
  alphaTest: 0.02,
  blending: THREE.NormalBlending
});
const clouds = new THREE.Mesh(cloudGeo, cloudMat);
earthGroup.add(clouds);

const atmoVertexShader = `
  varying vec3 vNormal;
  void main() {
    vNormal = normalize(normalMatrix * normal);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;
const atmoFragmentShader = `
  varying vec3 vNormal;
  void main() {
    float delta = 0.6 - dot(vNormal, vec3(0.0, 0.0, 1.0));
    float intensity = pow(delta, 3.5);
    gl_FragColor = vec4(0.4, 0.7, 1.0, 1.0) * intensity * 1.8;
  }
`;
const atmoGeo = new THREE.SphereGeometry(1.22, 64, 64);
const atmoMat = new THREE.ShaderMaterial({
  vertexShader: atmoVertexShader,
  fragmentShader: atmoFragmentShader,
  blending: THREE.AdditiveBlending,
  side: THREE.BackSide,
  transparent: true,
  depthWrite: false
});
const atmosphere = new THREE.Mesh(atmoGeo, atmoMat);
earthGroup.add(atmosphere);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(10, 128),
  new THREE.MeshStandardMaterial({
    color: 0xe6ecf5,
    roughness: 0.85,
    metalness: 0.05,
    envMapIntensity: 0.4
  })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -3;
floor.receiveShadow = true;
scene.add(floor);

camera.position.set(0, 0, 3.8);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 2.2;
controls.maxDistance = 10;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  earth.rotation.y = t * 0.04;
  clouds.rotation.y = t * 0.055;

  earthGroup.rotation.z = Math.sin(t * 0.08) * 0.03;
  earthGroup.rotation.x = Math.cos(t * 0.06) * 0.02;

  rimLight.intensity = 0.7 + Math.sin(t * 0.7) * 0.15;

  controls.update();
  renderer.render(scene, camera);
}
animate();

