    Math.cos(angle) * radius,
    Math.sin(i * 0.7) * 0.5,
    Math.sin(angle) * radius
  );
  mesh.userData = { angle: angle, speed: 0.5 + Math.random() * 0.5 };
  particleGroup.add(mesh);
}

