  ringGroup.rotation.y = t * 0.3;
  ring1.rotation.x = Math.PI / 2 + Math.sin(t * 0.4) * 0.2;
  ring2.rotation.y = t * 0.5;

  particleGroup.children.forEach((p, i) => {
    const angle = p.userData.angle + t * p.userData.speed * 0.3;
    p.position.x = Math.cos(angle) * 3.2;
    p.position.z = Math.sin(angle) * 3.2;
    p.position.y = Math.sin(t * 1.5 + i) * 0.3;
    p.rotation.x = t;
    p.rotation.y = t * 0.5;
  });

  rimLight.intensity = 0.4 + Math.sin(t * 1.2) * 0.15;
